sys_script.script:
/**
 * Before-save logic for Inventory Stock records.
 *
 * 1. Validates that Reserved Quantity never exceeds Total Quantity.
 * 2. Calculates Available Quantity = Total Quantity - Reserved Quantity.
 * 3. Sets Last Updated to the current date/time.
 */
(function executeRule(current, previous) {
    var totalQty = parseFloat(current.getValue('total_quantity')) || 0;
    var reservedQty = parseFloat(current.getValue('reserved_quantity')) || 0;

    // Validate: Reserved Quantity must never exceed Total Quantity
    if (reservedQty > totalQty) {
        gs.addErrorMessage(
            'Reserved Quantity (' + reservedQty +
            ') cannot be greater than Total Quantity (' + totalQty + ').'
        );
        current.setAbortAction(true);
        return;
    }

    // Calculate Available Quantity
    var availableQty = totalQty - reservedQty;
    current.setValue('available_quantity', availableQty.toString());

    // Set Last Updated to current date/time
    var now = new GlideDateTime();
    current.setValue('last_updated', now.getValue());
})(current, previous);
